        "Donor -> Donor Record",
        "Distribution Partner -> Distribution Partner Record"
      ]
    },
    "Governance": {
      "derived from": "Governance Subdomain",
      "objects": [
        "Government Food Inspector",
        "Evaluation Notice"
      ],
      "name changes": []
