        "Food Donor",
        "Available Food Items",
        "Pickup Times",
        "Donation Offer",
        "Food Donation",
        "Food Item",
        "Donation Volunteer"
      ],
      "name changes": [
        "Donor -> Food Donor",
        "Food Donation stays Food Donation",
        "Community Volunteer -> Donation Volunteer"
      ]
    },
    "Data Recording": {
      "derived from": "Data Recording Subdomain",
      "objects": [
        "Delivery Log",
        "Food Recovery Data",
        "Monthly Report",
        "Weekly Report"
      ],
